145	        currentOwner.setAddress(ownerFieldsDto.getAddress());
146	        currentOwner.setCity(ownerFieldsDto.getCity());
147	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
148	        currentOwner.setLastName(ownerFieldsDto.getLastName());
149	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
150	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
151	        this.clinicService.saveOwner(currentOwner);
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
