232	    /**
233	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where LAST3 is the
234	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
235	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
236	     *
237	     * @param lastName the owner's last name
238	     * @return the assigned customer code
239	     */
240	    private String nextCustomerCode(String lastName) {
241	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
242	        int sequence = this.clinicService.findAllOwners().size() + 1;
243	        return String.format("%s-%04d", prefix, sequence);
244	    }
245	
246	    /**
247	     * Counts the existing owners that already share the given first name and last name, comparing
248	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
249	     * the number of namesakes that existed prior to this create.
250	     *
251	     * @param firstName the new owner's first name
252	     * @param lastName  the new owner's last name
253	     * @return the number of existing owners with the same first and last name
254	     */
255	    private int countNamesakes(String firstName, String lastName) {
256	        int count = 0;
257	        for (Owner existing : this.clinicService.findAllOwners()) {
258	            if (firstName.equalsIgnoreCase(existing.getFirstName())
259	                && lastName.equalsIgnoreCase(existing.getLastName())) {
260	                count++;
261	            }
262	        }
263	        return count;
264	    }
265	
266	    /**
267	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
268	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
269	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
270	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
271	     * string is what gets stored and returned.
272	     *
273	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
274	     *
275	     * @param telephone the raw telephone value supplied by the client
276	     * @return the normalized E.164 telephone number
277	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
278	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
279	     *                                 digits after the {@code '+'})
280	     */
281	    private static String normalizeTelephone(String telephone) {
282	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
283	        String digits;
284	        if (cleaned.startsWith("+")) {
285	            digits = cleaned.substring(1);
286	        } else {
287	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
288	            digits = "61" + national;
289	        }
290	        if (!digits.matches("[0-9]{8,15}")) {
291	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
292	                "telephone could not be normalized to a valid E.164 number");
293	        }
294	        return "+" + digits;
295	    }
296	
297	    /**
298	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
299	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
300	     *
301	     * @param telephone the stored telephone value, possibly {@code null}
302	     * @return the E.164 form, or the raw value when it cannot be normalized
303	     */
304	    private static String toComparableTelephone(String telephone) {
305	        try {
306	            return normalizeTelephone(telephone);
307	        } catch (ResponseStatusException ex) {
308	            return telephone;
309	        }
310	    }
311	
312	    /**
313	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
314	     * containing at least one dot, none of the three sections containing whitespace or an
315	     * additional {@code @}.
316	     */
317	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
318	
319	    /**
320	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
321	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
322	     * value is then stored and returned lower-cased.
323	     *
324	     * @param email the raw email value supplied by the client, possibly {@code null}
325	     * @return the lower-cased email, or {@code null} when none was supplied
326	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
327	     *                                 is not a syntactically valid address
328	     */
329	    private static String normalizeEmail(String email) {
330	        if (email == null) {
331	            return null;
332	        }
333	        if (!EMAIL_PATTERN.matcher(email).matches()) {
334	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
335	                "email must be a syntactically valid address");
336	        }
337	        return email.toLowerCase(Locale.ROOT);
338	    }
339	
340	    /**
341	     * Common street-type abbreviations expanded to their full word during address normalization.
342	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
343	     */
344	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
345	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
346	
347	    /**
348	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
349	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
350	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
351	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
352	     * address comparison (household duplicate detection and the shared household id).
353	     *
354	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
355	     *
356	     * @param address the raw address supplied by the client, possibly {@code null}
357	     * @return the normalized address
358	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
359	     *                                 after normalization (required field)
360	     */
361	    private static String normalizeAddress(String address) {
362	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
363	        if (collapsed.isEmpty()) {
364	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
365	                "address must not be blank");
366	        }
367	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
368	        StringBuilder normalized = new StringBuilder();
369	        for (int i = 0; i < tokens.length; i++) {
370	            if (i > 0) {
371	                normalized.append(' ');
372	            }
373	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
374	        }
375	        return normalized.toString();
376	    }
377	
378	    /**
379	     * Determines whether the given normalized E.164 telephone is already used by any owner other
380	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
381	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
382	     * inputs representing the same number are treated as duplicates.
383	     *
384	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
385	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
386	     * @return {@code true} if another owner already uses the telephone
387	     */
388	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
389	        for (Owner existing : this.clinicService.findAllOwners()) {
390	            if (excludeId != null && excludeId.equals(existing.getId())) {
391	                continue;
392	            }
393	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
394	                return true;
395	            }
396	        }
397	        return false;
398	    }
399	
400	}
